/**
 * One stop on the walk. Selecting a step opens `file` in the editor and
 * highlights lines `startLine` through `endLine` (both 1-based and inclusive).
 */
export interface CodewalkStep {
  /** Short field — inline markdown only. See {@link CodewalkStep.narration}. */
  title: string;
  /** Path relative to the workspace root, using forward slashes. */
  file: string;
  /** First line of the region, 1-based and inclusive. */
  startLine: number;
  /** Last line of the region, 1-based and inclusive; must be >= `startLine`. */
  endLine: number;

export async function listWalkFiles(
  workspaceRoot: string,
  getAttempt?: (filePath: string, ref: string) => AttemptSummary | undefined,
  getProgress?: (filePath: string, ref: string) => WalkProgressSummary | undefined,
): Promise<WalkFileSummary[]> {
  const filePaths = await findCodewalkFiles(workspaceRoot);
  // 並行讀取:Promise.all 保證回傳順序等同 filePaths,與檔案讀完的先後無關
  return Promise.all(
    filePaths.map(async (filePath) => {
      const result = await loadCodewalkFile(filePath);
      const summary: WalkFileSummary = {
        path: filePath,
        title: result.valid ? result.value.title : basename(filePath),
      };

