  const currentSlice = fileLines.slice(startLine - 1, endLine).join('\n');
  if (currentSlice === normalizedAnchor) {
    return { kind: 'matched' };
  }

  const whole = fileLines.join('\n');
  const offsets = findLineAlignedOffsets(whole, normalizedAnchor);
  if (offsets.length === 0) {
    return { kind: 'stale', reason: 'notFound' };
  }
  if (offsets.length > 1) {
    return { kind: 'stale', reason: 'ambiguous' };
  }

  const newStartLine = lineNumberAtOffset(whole, offsets[0]);
  const anchorLineCount = normalizedAnchor.split('\n').length;
  return {
    kind: 'shifted',
    startLine: newStartLine,
    endLine: newStartLine + anchorLineCount - 1,
  };
}

/** 解析出的 `open` 請求;`uri.path` 不是 `/open` 或缺少 `walk` 參數時為 `null`。 */
export function parseOpenUri(uri: OpenUriLike): { walk: string; stepIndex?: number } | null {
  if (uri.path !== '/open') return null;
  const params = new URLSearchParams(uri.query);
  const walk = params.get('walk');
  if (!walk) return null;
  const stepParam = params.get('step');
  if (stepParam === null) return { walk };
  const stepIndex = Number(stepParam);
  if (!Number.isInteger(stepIndex) || stepIndex < 0) return { walk };
  return { walk, stepIndex };
}
